/* Original procedural stone bridge and ice. Shared world-to-minimap atlas. */
window.createARAMGround=function(C,local=false){let canvas=document.createElement('canvas');canvas.width=canvas.height=C.mapTextureSize;let g=canvas.getContext('2d'),a=C.aram,y=a.bridge_center_y,w=a.bridge_width;g.scale(C.mapTextureSize/C.world,C.mapTextureSize/C.world);g.fillStyle='#0b172b';g.fillRect(0,0,C.world,C.world);let gradient=g.createLinearGradient?.(0,y-w,0,y+w);if(gradient){gradient.addColorStop(0,'#0a162c');gradient.addColorStop(.5,'#28435f');gradient.addColorStop(1,'#0b1d34');g.fillStyle=gradient;g.fillRect(0,y-w*2,C.world,w*4)}if(!local){g.translate(C.world/2,C.world/2);g.rotate((a.orientation_degrees||0)*Math.PI/180);g.translate(-C.world/2,-C.world/2)}g.fillStyle='#8da6b9';g.fillRect(a.bridge_min_x,y-w/2,a.bridge_max_x-a.bridge_min_x,w);for(let row=0;row<12;row++)for(let col=0;col<70;col++){let x=a.bridge_min_x+col*210+(row%2)*105,yy=y-w/2+row*w/12;g.fillStyle=(row+col)%4===0?'#afc5d2':'#708997';g.fillRect(x+4,yy+4,200,w/12-8)}for(let sign of [-1,1]){g.fillStyle='#d0e6ee';g.fillRect(a.bridge_min_x,y+sign*w/2-22,a.bridge_max_x-a.bridge_min_x,44);for(let x=1000;x<14000;x+=600){g.fillStyle='#465d73';g.fillRect(x,y+sign*(w/2+60)-50,100,100);g.fillStyle='#b8d8e8';g.fillRect(x+10,y+sign*(w/2+60)-40,80,80)}}for(let b of a.bushes){g.fillStyle='#517689';g.fillRect(b.x-b.w/2,b.y-b.h/2,b.w,b.h);g.strokeStyle='#a9d9d9';g.lineWidth=5;for(let x=b.x-b.w/2;x<b.x+b.w/2;x+=40){g.beginPath();g.moveTo(x,b.y+b.h/2);g.lineTo(x+15,b.y-b.h/2);g.stroke()}}for(let [i,b]of a.bases.entries()){g.beginPath();g.arc(b.x,b.y,a.shop_radius,0,Math.PI*2);g.fillStyle=i?'#633d58':'#315c7e';g.fill();g.lineWidth=20;g.strokeStyle=i?'#efb1c9':'#9ce5ff';g.stroke()}for(let p of [...a.relic_positions,...a.portal_positions]){g.beginPath();g.arc(p.x,p.y,80,0,Math.PI*2);g.strokeStyle='#c1e5e4';g.lineWidth=12;g.stroke()}return canvas;};
